import {CLASSROOM_API} from './classroom-config.js';
import {mobilePlatform,installInstructions} from './mobile.js?v=20261012-logout1';
export function appSetup(teacher=false,origin='https://richmount-ielts.onrender.com'){return {teacher,label:teacher?'Teacher app':'Student app',openLabel:teacher?'Open your dashboard →':'Open the studio →',start:teacher?'/#teacher/overview':'/#home',link:origin+'/install.html',qr:teacher?'assets/teacher-app-qr.svg':'assets/student-app-qr.svg',description:teacher?'Your teaching dashboard, guided lessons, class resources and student work, one tap from your home screen.':'Your IELTS lessons, homework, mock tests and writing practice, one tap from your home screen.'};}
export function phoneSteps(platform='android'){return platform==='ios'?['Open this setup link in Safari on your iPhone or iPad.','Tap Share, or open the page menu and choose Share.','Choose Add to Home Screen. Keep Open as Web App enabled if it appears, then tap Add.','Open Richmount from your home screen and sign in to your class.']:['Open this setup link in Chrome on your Android phone.','Tap Install on this device. If an install prompt appears, confirm Install.','If no prompt appears, open Chrome’s ⋮ menu and choose Install app or Add to Home screen.','Open Richmount from your home screen and sign in to your class.'];}
export function initAppSetup({win=window,doc=document,nav=navigator,api=CLASSROOM_API}={}){
 const teacher=doc.body.dataset.appRole==='teacher'||!!api&&api.replace(/\/$/,'')===win.location.origin,setup=appSetup(teacher,win.location.origin),platform=mobilePlatform(nav),inApp=/FBAN|FBAV|Instagram|; wv\)/i.test(nav.userAgent||'');
 const status=doc.querySelector('#installStatus'),install=doc.querySelector('#installAppButton'),steps=doc.querySelector('#deviceSteps'),link=doc.querySelector('#appInstallLink'),copy=doc.querySelector('#copyAppLink'),copyStatus=doc.querySelector('#copyStatus');let deferred=null,installed=win.matchMedia('(display-mode: standalone)').matches||nav.standalone===true;
 doc.querySelector('[data-role-label]').textContent=setup.label;doc.querySelector('[data-role-description]').textContent=setup.description;doc.querySelector('[data-open-label]').textContent=setup.openLabel;doc.querySelectorAll('[data-studio-link]').forEach(a=>a.href=setup.start);doc.querySelector('#appQRCode').src=setup.qr;doc.querySelector('#appQRCode').alt='QR code for the Richmount '+(teacher?'teacher':'student')+' app setup page';link.value=setup.link;
 if(teacher){doc.querySelector('[data-signin-title]').textContent='Use your usual teacher password.';doc.querySelector('[data-signin-description]').textContent='Sign in to your private teacher dashboard inside the app. Your materials, student work and feedback stay protected.';doc.querySelector('[data-feature-label]').textContent='Student work & feedback';}
 const manifest=doc.querySelector('link[rel="manifest"]');if(teacher&&manifest)manifest.href='teacher.webmanifest';doc.querySelector('#browserNotice').hidden=!inApp;
 function showDevice(device){for(const b of doc.querySelectorAll('[data-device]')){const selected=b.dataset.device===device;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));}steps.innerHTML=phoneSteps(device).map(s=>'<li>'+s+'</li>').join('');}
 function installedState(){installed=true;deferred=null;install.hidden=true;status.textContent='Richmount is ready on this device. Open the studio or launch it from your home screen.';}
 showDevice(platform==='ios'?'ios':'android');for(const b of doc.querySelectorAll('[data-device]'))b.addEventListener('click',()=>showDevice(b.dataset.device));if(installed)installedState();
 win.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;if(!installed)install.hidden=false;});win.addEventListener('appinstalled',installedState);
 install.addEventListener('click',async()=>{if(installed)return;if(deferred){const prompt=deferred;deferred=null;install.disabled=true;try{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted'){status.textContent='Installation requested. Look for Richmount on your home screen.';return;}}catch{}finally{install.disabled=false;}}status.textContent=installInstructions(platform,inApp);doc.querySelector('#deviceGuide').scrollIntoView({behavior:win.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
 copy.addEventListener('click',async()=>{try{await nav.clipboard.writeText(setup.link);copyStatus.textContent='App setup link copied.';}catch{link.focus();link.select();copyStatus.textContent='Select and copy the link shown above.';}});
 if('serviceWorker' in nav&&win.isSecureContext)nav.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).catch(()=>{});
 return {setup,showDevice,get installed(){return installed;}};
}
if(typeof document!=='undefined'&&document.querySelector('#installAppButton'))initAppSetup();
